"use client";
import * as React from "react";
import { cn } from "../lib/cn";
import { Icon, type IconName } from "../icons/icon";

export type ToolCallStatus = "pending" | "running" | "success" | "error";

export interface ToolCallProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "title"> {
  /** Naam van het gereedschap, bv. "zoek_klant". */
  name: React.ReactNode;
  status?: ToolCallStatus;
  icon?: IconName;
  /** Korte samenvatting op de regel zelf, bv. "3 resultaten". */
  summary?: React.ReactNode;
  /** Wat erin ging; wordt als JSON getoond wanneer het geen string is. */
  input?: unknown;
  /** Wat eruit kwam. */
  output?: unknown;
  /** Foutmelding bij status "error". */
  error?: React.ReactNode;
  /** Duur in milliseconden. */
  duration?: number;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Compacte chip in plaats van een kaart. */
  compact?: boolean;
}

const ICOON: Record<ToolCallStatus, IconName> = {
  pending: "clock",
  running: "loader",
  success: "check",
  error: "alertCircle",
};

const alsTekst = (waarde: unknown) => {
  if (waarde === undefined || waarde === null) return "";
  if (typeof waarde === "string") return waarde;
  try {
    return JSON.stringify(waarde, null, 2);
  } catch {
    return String(waarde);
  }
};

/**
 * ToolCall — regel die laat zien welk gereedschap een model aanriep, met welke
 * invoer, en wat eruit kwam. Dichtgeklapt is het één regel; open zie je alles.
 */
export const ToolCall = React.forwardRef<HTMLDivElement, ToolCallProps>(function ToolCall(
  {
    name,
    status = "success",
    icon,
    summary,
    input,
    output,
    error,
    duration,
    open,
    defaultOpen,
    onOpenChange,
    compact,
    className,
    ...rest
  },
  ref
) {
  const [intern, setIntern] = React.useState(defaultOpen ?? false);
  const uitgeklapt = open ?? intern;
  const zetOpen = (waarde: boolean) => {
    if (open === undefined) setIntern(waarde);
    onOpenChange?.(waarde);
  };

  const invoer = alsTekst(input);
  const uitvoer = alsTekst(output);
  const heeftDetails = Boolean(invoer || uitvoer || error);

  return (
    <div
      ref={ref}
      className={cn("lui-toolcall", compact && "lui-toolcall-compact", className)}
      data-status={status}
      data-open={uitgeklapt ? "" : undefined}
      {...rest}
    >
      <button
        type="button"
        className="lui-toolcall-head"
        onClick={() => zetOpen(!uitgeklapt)}
        aria-expanded={heeftDetails ? uitgeklapt : undefined}
        disabled={!heeftDetails}
      >
        <span className="lui-toolcall-mark">
          <Icon name={icon ?? ICOON[status]} size={13} />
        </span>
        <span className="lui-toolcall-name">{name}</span>
        {summary && <span className="lui-toolcall-summary">{summary}</span>}
        {duration !== undefined && (
          <span className="lui-toolcall-duration">
            {duration < 1000 ? `${Math.round(duration)} ms` : `${(duration / 1000).toFixed(1)} s`}
          </span>
        )}
        {heeftDetails && <span className="lui-toolcall-chevron" aria-hidden="true" />}
      </button>

      {uitgeklapt && heeftDetails && (
        <div className="lui-toolcall-body">
          {invoer && (
            <div className="lui-toolcall-part">
              <span className="lui-toolcall-part-label">Invoer</span>
              <pre className="lui-toolcall-pre">{invoer}</pre>
            </div>
          )}
          {error ? (
            <div className="lui-toolcall-part">
              <span className="lui-toolcall-part-label">Fout</span>
              <p className="lui-toolcall-error">{error}</p>
            </div>
          ) : (
            uitvoer && (
              <div className="lui-toolcall-part">
                <span className="lui-toolcall-part-label">Resultaat</span>
                <pre className="lui-toolcall-pre">{uitvoer}</pre>
              </div>
            )
          )}
        </div>
      )}
    </div>
  );
});

export interface ApprovalCardProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "title" | "onSelect"> {
  title: React.ReactNode;
  description?: React.ReactNode;
  /** Regeltjes met wat er precies gaat gebeuren. */
  details?: Array<{ label: React.ReactNode; value: React.ReactNode }>;
  icon?: IconName;
  tone?: "accent" | "amber" | "red";
  onApprove?: (always: boolean) => void;
  onDeny?: () => void;
  approveLabel?: string;
  denyLabel?: string;
  /** Vinkje "altijd toestaan" bij de goedkeuring. */
  allowAlways?: boolean;
  alwaysLabel?: string;
  /** Uitkomst tonen in plaats van de knoppen. */
  decision?: "approved" | "denied" | null;
  disabled?: boolean;
}

/**
 * ApprovalCard — vraagt toestemming voor één handeling, met de details erbij
 * zodat je weet waar je ja op zegt.
 */
export const ApprovalCard = React.forwardRef<HTMLDivElement, ApprovalCardProps>(function ApprovalCard(
  {
    title,
    description,
    details,
    icon = "shield",
    tone = "amber",
    onApprove,
    onDeny,
    approveLabel = "Toestaan",
    denyLabel = "Weigeren",
    allowAlways,
    alwaysLabel = "Altijd toestaan",
    decision,
    disabled,
    className,
    ...rest
  },
  ref
) {
  const [altijd, setAltijd] = React.useState(false);

  return (
    <div ref={ref} className={cn("lui-approval", className)} data-tone={tone} role="group" {...rest}>
      <div className="lui-approval-head">
        <span className="lui-approval-icon">
          <Icon name={icon} size={16} />
        </span>
        <div className="lui-approval-text">
          <p className="lui-approval-title">{title}</p>
          {description && <p className="lui-approval-desc">{description}</p>}
        </div>
      </div>

      {details && details.length > 0 && (
        <dl className="lui-approval-details">
          {details.map((regel, index) => (
            <div className="lui-approval-row" key={index}>
              <dt>{regel.label}</dt>
              <dd>{regel.value}</dd>
            </div>
          ))}
        </dl>
      )}

      {decision ? (
        <p className="lui-approval-decision" data-decision={decision}>
          <Icon name={decision === "approved" ? "checkCircle" : "xCircle"} size={15} />
          {decision === "approved" ? "Toegestaan" : "Geweigerd"}
        </p>
      ) : (
        <div className="lui-approval-actions">
          {allowAlways && (
            <label className="lui-approval-always">
              <input type="checkbox" checked={altijd} onChange={(e) => setAltijd(e.target.checked)} />
              {alwaysLabel}
            </label>
          )}
          <button
            type="button"
            className="lui-approval-btn"
            onClick={onDeny}
            disabled={disabled}
          >
            {denyLabel}
          </button>
          <button
            type="button"
            className="lui-approval-btn"
            data-primary=""
            onClick={() => onApprove?.(altijd)}
            disabled={disabled}
          >
            {approveLabel}
          </button>
        </div>
      )}
    </div>
  );
});

/* ==================== ToolCall & ApprovalCard ==================== */
.lui-toolcall {
  border: 1px solid var(--border); border-radius: var(--r-sm);
  background: var(--surface); overflow: hidden;
}
.lui-toolcall-compact { border-radius: var(--r-full); }
.lui-toolcall-compact[data-open] { border-radius: var(--r-sm); }

.lui-toolcall-head {
  display: flex; align-items: center; gap: 8px; width: 100%;
  padding: 7px 11px; border: 0; background: transparent;
  font: inherit; font-size: 13px; color: var(--text-2); text-align: start; cursor: pointer;
}
.lui-toolcall-head:disabled { cursor: default; }
.lui-toolcall-head:hover:not(:disabled) { background: var(--surface-2); }
.lui-toolcall-head:focus-visible { outline: none; box-shadow: var(--ring); }

.lui-toolcall-mark {
  display: grid; place-items: center; flex: none; width: 20px; height: 20px;
  border-radius: 50%; background: var(--surface-3); color: var(--text-3);
}
.lui-toolcall[data-status="success"] .lui-toolcall-mark { background: color-mix(in oklab, var(--green) 16%, transparent); color: var(--green); }
.lui-toolcall[data-status="error"] .lui-toolcall-mark { background: color-mix(in oklab, var(--red) 16%, transparent); color: var(--red); }
.lui-toolcall[data-status="running"] .lui-toolcall-mark { background: color-mix(in oklab, var(--accent) 16%, transparent); color: var(--accent); }
.lui-toolcall[data-status="running"] .lui-toolcall-mark > svg { animation: lui-toolcall-spin 1s linear infinite; }
@keyframes lui-toolcall-spin { to { transform: rotate(360deg); } }

.lui-toolcall-name { font-family: var(--mono); font-weight: 600; color: var(--text); }
.lui-toolcall-summary {
  flex: 1; min-width: 0; color: var(--text-3);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.lui-toolcall-duration { flex: none; font-size: 11.5px; color: var(--text-3); font-variant-numeric: tabular-nums; }
.lui-toolcall-chevron {
  flex: none; width: 6px; height: 6px; border-right: 1.5px solid var(--text-3); border-bottom: 1.5px solid var(--text-3);
  transform: rotate(45deg) translate(-1px, -1px); transition: transform var(--dur-fast);
}
.lui-toolcall[data-open] .lui-toolcall-chevron { transform: rotate(225deg) translate(-1px, -1px); }

.lui-toolcall-body { display: grid; gap: 10px; padding: 10px 11px 12px; border-top: 1px solid var(--border); }
.lui-toolcall-part { display: grid; gap: 4px; }
.lui-toolcall-part-label {
  font-size: 10.5px; font-weight: 650; letter-spacing: .07em; text-transform: uppercase; color: var(--text-3);
}
.lui-toolcall-pre {
  margin: 0; padding: 9px 11px; overflow-x: auto; max-height: 260px;
  border-radius: var(--r-xs); background: var(--surface-2);
  font-family: var(--mono); font-size: 12px; line-height: 1.6; color: var(--text-2);
}
.lui-toolcall-error { margin: 0; font-size: 13px; color: var(--red); }

/* ---------- ApprovalCard ---------- */
.lui-approval {
  display: grid; gap: 12px; padding: 14px;
  border: 1px solid var(--border); border-radius: var(--r-md); background: var(--surface);
  border-inline-start: 3px solid var(--amber);
}
.lui-approval[data-tone="accent"] { border-inline-start-color: var(--accent); }
.lui-approval[data-tone="red"] { border-inline-start-color: var(--red); }

.lui-approval-head { display: flex; align-items: flex-start; gap: 10px; }
.lui-approval-icon {
  display: grid; place-items: center; flex: none; width: 30px; height: 30px;
  border-radius: var(--r-sm); background: color-mix(in oklab, var(--amber) 15%, transparent); color: var(--amber);
}
.lui-approval[data-tone="accent"] .lui-approval-icon { background: color-mix(in oklab, var(--accent) 15%, transparent); color: var(--accent); }
.lui-approval[data-tone="red"] .lui-approval-icon { background: color-mix(in oklab, var(--red) 15%, transparent); color: var(--red); }

.lui-approval-text { display: grid; gap: 3px; }
.lui-approval-title { margin: 0; font-size: var(--fs-sm); font-weight: 650; color: var(--text); }
.lui-approval-desc { margin: 0; font-size: 13px; color: var(--text-3); line-height: 1.55; }

.lui-approval-details {
  display: grid; gap: 6px; margin: 0; padding: 10px 12px;
  border-radius: var(--r-sm); background: var(--surface-2);
}
.lui-approval-row { display: flex; align-items: baseline; gap: 12px; justify-content: space-between; }
.lui-approval-row dt { font-size: 12.5px; color: var(--text-3); }
.lui-approval-row dd {
  margin: 0; font-size: 12.5px; color: var(--text); font-family: var(--mono);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}

.lui-approval-actions { display: flex; align-items: center; justify-content: flex-end; gap: 8px; flex-wrap: wrap; }
.lui-approval-always {
  display: flex; align-items: center; gap: 6px; margin-inline-end: auto;
  font-size: 12.5px; color: var(--text-3); cursor: pointer;
}
.lui-approval-btn {
  height: 32px; padding: 0 14px; border: 1px solid var(--border-strong); border-radius: var(--r-sm);
  background: var(--surface); color: var(--text-2);
  font: inherit; font-size: var(--fs-sm); font-weight: 600; cursor: pointer;
  transition: background var(--dur-fast), color var(--dur-fast);
}
.lui-approval-btn:hover:not(:disabled) { background: var(--surface-2); color: var(--text); }
.lui-approval-btn[data-primary] { background: var(--accent); border-color: var(--accent); color: var(--accent-fg); }
.lui-approval-btn[data-primary]:hover:not(:disabled) { background: var(--accent-hover); color: var(--accent-fg); }
.lui-approval-btn:focus-visible { outline: none; box-shadow: var(--ring); }
.lui-approval-btn:disabled { opacity: .5; cursor: not-allowed; }

.lui-approval-decision {
  display: flex; align-items: center; gap: 7px; margin: 0;
  font-size: var(--fs-sm); font-weight: 600;
}
.lui-approval-decision[data-decision="approved"] { color: var(--green); }
.lui-approval-decision[data-decision="denied"] { color: var(--text-3); }
